<script setup>
import {onMounted,ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({agencyId:{type:Number,required:true},claimId:{type:Number,required:true}});const emit=defineEmits(['updated','edit-defaults']);
const proofFile=ref(null),proofs=ref([]),proofIds=ref([]),reference=ref('');
const data=ref(null),busy=ref(false),error=ref(''),notice=ref(''),editing=ref(false),amount=ref(''),copay=ref(''),percentage=ref(''),reason=ref(''),mode=ref('estimate'),confirmed=ref(false),historyFilter=ref('client');
const money=v=>v==null?'Not recorded':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);
const dollars=v=>v==null?'':(v/100).toFixed(2);
async function load(){busy.value=true;error.value='';try{data.value=(await api.get(`/medical-billing/claimmd/claims/${props.claimId}/financial-review`,{params:{agencyId:props.agencyId},skipGlobalLoading:true})).data;amount.value=dollars(data.value.estimate?.amountCents);copay.value=dollars(data.value.estimate?.copayCents??data.value.policy.copayCents);percentage.value=(data.value.estimate?.coinsuranceBasisPoints??data.value.policy.coinsuranceBasisPoints)==null?'':String((data.value.estimate?.coinsuranceBasisPoints??data.value.policy.coinsuranceBasisPoints)/100);}catch(e){error.value=e.response?.data?.error?.message||'Patient responsibility and reimbursement history could not be loaded.';}finally{busy.value=false;}}
function cents(raw){if(String(raw).trim()==='')return null;if(!/^\d+(\.\d{1,2})?$/.test(String(raw)))throw new Error('Enter dollars or a percentage with at most two decimal places.');return Math.round(Number(raw)*100);}
async function save(){busy.value=true;error.value='';notice.value='';try{
 if(reason.value.trim().length<10)throw new Error('Explain the source of the amount.');
 if(mode.value==='final'){
  if(!confirmed.value||!proofIds.value.length)throw new Error('Upload final payer proof and confirm your review.');
  const result=await api.post(`/medical-billing/claimmd/claims/${props.claimId}/patient-responsibility`,{agencyId:props.agencyId,amountCents:cents(amount.value),reason:reason.value.trim(),reference:reference.value.trim(),evidenceIds:proofIds.value,attested:true},{skipGlobalLoading:true});notice.value=result.data.message;
 }else if(mode.value==='copay'){
  if(!confirmed.value||cents(copay.value)==null)throw new Error('Confirm the verified copay and its source.');
  await api.post(`/family-ledger/staff/claims/${props.claimId}/responsibility`,{agencyId:props.agencyId,clientId:data.value.clientId,amountCents:cents(copay.value),responsibilityType:'copay',verificationBasis:'benefit',reason:reason.value.trim()},{skipGlobalLoading:true});
  notice.value='Verified copay recorded in the existing patient ledger. No card was charged by this action.';
 }else{
  const result=await api.post(`/medical-billing/claimmd/claims/${props.claimId}/patient-estimate`,{agencyId:props.agencyId,revision:data.value.revision,amountCents:cents(amount.value),copayCents:cents(copay.value),coinsuranceBasisPoints:cents(percentage.value),reason:reason.value.trim()},{skipGlobalLoading:true});notice.value=result.data.message;
 }
 editing.value=false;await load();emit('updated');
 }catch(e){error.value=e.response?.data?.error?.message||e.message||'The patient share was not saved.';}finally{busy.value=false;}}
async function loadProof(){try{proofs.value=(await api.get(`/medical-billing/claims/${props.claimId}/responsibility-proof`,{params:{agencyId:props.agencyId},skipGlobalLoading:true})).data.items||[];}catch(e){error.value=e.response?.data?.error?.message||'Final payer proof could not be loaded.';}}
async function uploadProof(){if(!proofFile.value||reference.value.trim().length<3)return;busy.value=true;error.value='';try{const form=new FormData();form.append('file',proofFile.value);form.append('kind',/\.(835|edi|txt)$/i.test(proofFile.value.name)?'final_era':'final_eob');form.append('source',reference.value.trim());const {data:uploaded}=await api.post(`/medical-billing/claims/${props.claimId}/responsibility-proof`,form,{params:{agencyId:props.agencyId},skipGlobalLoading:true});proofIds.value=[...proofIds.value,uploaded.item.id];await loadProof();}catch(e){error.value=e.response?.data?.error?.message||'Proof upload failed; no patient balance was posted.';}finally{busy.value=false;}}
watch(mode,value=>{confirmed.value=false;if(value==='final')loadProof();});
onMounted(load);
</script>
<template><section class="financial-review" aria-label="Patient responsibility and reimbursements"><h3>Patient responsibility</h3><p v-if="busy" role="status">Loading or saving billing details…</p><p v-if="error" role="alert">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
 <template v-if="data"><dl><div><dt>Payer-reported / saved copay</dt><dd>{{ money(data.policy.copayCents) }}</dd></div><div><dt>Coinsurance</dt><dd>{{ data.policy.coinsuranceBasisPoints==null?'Not recorded':`${data.policy.coinsuranceBasisPoints/100}%` }}</dd></div><div><dt>Final patient responsibility</dt><dd>{{ data.hasFinalPatientResponsibility?money(data.finalPatientResponsibilityCents):'Awaiting adjudication' }}</dd></div><div><dt>Billing estimate</dt><dd>{{ money(data.estimate?.amountCents) }}<small v-if="data.estimate?.coinsuranceBasisPoints!=null"> · {{ data.estimate.coinsuranceBasisPoints/100 }}% coinsurance (reviewed estimate)</small></dd></div></dl>
 <p>{{ data.message }}</p><p v-if="data.policy.secondaryCoverage">Secondary coverage is recorded. Reconcile the final payer before assigning a final patient balance.</p>
 <div v-for="balance in data.balances" :key="balance.id">Patient ledger · {{ money(balance.amount_cents) }} responsibility · {{ money(balance.paid_cents) }} paid · {{ money(balance.dueCents) }} due</div>
 <button type="button" @click="editing=!editing">{{ editing?'Close patient share editor':'Edit patient responsibility / copay' }}</button>
 <form v-if="editing" @submit.prevent="save"><label>Record as<select v-model="mode"><option value="estimate">Billing estimate only</option><option value="copay">Verified copay in patient ledger</option><option value="final">Final ERA/EOB patient responsibility</option></select></label><label v-if="mode!=='copay'">{{ mode==='final'?'Final patient responsibility in dollars':'Estimated responsibility in dollars' }}<input v-model="amount" inputmode="decimal" /></label><label v-if="mode!=='final'">Copay in dollars<input v-model="copay" inputmode="decimal" /></label><label v-if="mode==='estimate'">Coinsurance percentage<input v-model="percentage" inputmode="decimal" placeholder="For example, 20" /></label><label>Verification source / reason<textarea v-model="reason" minlength="10" maxlength="1000" required /></label><fieldset v-if="mode==='final'"><legend>Final payer ERA/EOB proof</legend><label>Payer reference / source<input v-model="reference" minlength="3" maxlength="255" /></label><input type="file" accept=".pdf,.png,.jpg,.jpeg,.835,.edi,.txt" @change="proofFile=$event.target.files?.[0]||null" /><button type="button" :disabled="busy||!proofFile||reference.trim().length<3" @click="uploadProof">Upload proof</button><label v-for="file in proofs.filter(file=>['final_eob','final_era'].includes(file.kind))" :key="file.id"><input v-model="proofIds" type="checkbox" :value="file.id" /> {{ file.filename }} · {{ file.source }}</label></fieldset>
 <label v-if="mode!=='estimate'"><input v-model="confirmed" type="checkbox" /> I reviewed {{ mode==='final'?'the final payer ERA/EOB and all coverage':'this copay' }} for the completed visit. This action records responsibility; it does not run a card.</label><p>Final deductible, coinsurance, and other patient balances require the final payer’s ERA/EOB proof. With secondary insurance, use the final secondary claim; estimates stay separate from amounts owed.</p><button :disabled="busy||reason.trim().length<10">Save patient share</button></form>
 <aside v-for="flag in data.flags" :key="flag.code" role="status">{{ flag.message }} <button type="button" @click="emit('edit-defaults')">Edit defaults</button></aside>
 <details><summary>Prior reimbursements for matching services and payer ({{ data.history.length }})</summary><label>Show<select v-model="historyFilter"><option value="client">This client</option><option value="provider">This provider</option><option value="payer">This payer</option></select></label><p v-if="!data.history.length">No posted reimbursements found. A clearinghouse acknowledgement is not a payment.</p><div v-for="row in data.history.filter(row=>historyFilter==='payer'||historyFilter==='client'&&row.same_client||historyFilter==='provider'&&row.same_provider)" :key="row.id" class="payment-history"><strong>{{ String(row.date_of_service).slice(0,10) }}</strong> · billed {{ money(row.billed_cents) }} · paid {{ money(row.paid_cents) }} · adjustment {{ money(row.adjustment_cents-row.responsibility_cents) }}<p v-for="flag in row.flags" :key="flag.code">{{ flag.message }}</p></div></details>
 </template></section></template>
<style scoped>.financial-review{padding:16px;border:1px solid #c6d3e0;border-radius:10px;margin:16px 0}dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}dt{font-size:12px;color:#52677c}dd{margin:5px 0;font-weight:600}label{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}p{font-size:13px;line-height:1.5}input,select,textarea,button{font:inherit;border:1px solid #bdcad8;border-radius:6px;padding:8px}button{cursor:pointer}aside{padding:12px;margin:12px 0;background:#fff4d9;color:#64460c;border-radius:8px}[role=alert]{color:#a12222}.payment-history{padding:10px 0;border-bottom:1px solid #e1e8ef}</style>
